#!/bin/bash\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Banner\necho -e \"${BLUE}\"\necho \"╔════════════════════════════════════════════════════════════════╗\"\necho \"║   🚀 ADAPTIVE LEARNING PLATFORM - LOCAL SETUP                  ║\"\necho \"║   100% Gratuit et Open-Source                                  ║\"\necho \"╚════════════════════════════════════════════════════════════════╝\"\necho -e \"${NC}\"\n\n# Function to print section headers\nprint_section() {\n    echo -e \"\\n${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}\"\n    echo -e \"${YELLOW}$1${NC}\"\n    echo -e \"${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}\\n\"\n}\n\n# Check Node.js\nprint_section \"1️⃣  Vérification de Node.js\"\nif ! command -v node &> /dev/null; then\n    echo -e \"${RED}❌ Node.js n'est pas installé${NC}\"\n    echo -e \"${YELLOW}📥 Téléchargez depuis: https://nodejs.org (v18+)${NC}\"\n    exit 1\nfi\necho -e \"${GREEN}✅ Node.js: $(node --version)${NC}\"\necho -e \"${GREEN}✅ npm: $(npm --version)${NC}\"\n\n# Check Docker\nprint_section \"2️⃣  Vérification de Docker\"\nif ! command -v docker &> /dev/null; then\n    echo -e \"${RED}❌ Docker n'est pas installé${NC}\"\n    echo -e \"${YELLOW}📥 Téléchargez depuis: https://docker.com/products/docker-desktop${NC}\"\n    exit 1\nfi\necho -e \"${GREEN}✅ Docker: $(docker --version)${NC}\"\n\nif ! command -v docker-compose &> /dev/null; then\n    echo -e \"${RED}❌ Docker Compose n'est pas installé${NC}\"\n    exit 1\nfi\necho -e \"${GREEN}✅ Docker Compose: $(docker-compose --version)${NC}\"\n\n# Check if Docker daemon is running\nif ! docker info > /dev/null 2>&1; then\n    echo -e \"${RED}❌ Le démon Docker n'est pas en cours d'exécution${NC}\"\n    echo -e \"${YELLOW}💡 Veuillez démarrer Docker Desktop${NC}\"\n    exit 1\nfi\necho -e \"${GREEN}✅ Docker daemon est actif${NC}\"\n\n# Install dependencies\nprint_section \"3️⃣  Installation des dépendances\"\necho -e \"${YELLOW}📦 npm install en cours...${NC}\"\nif npm install --legacy-peer-deps > /dev/null 2>&1; then\n    echo -e \"${GREEN}✅ Dépendances installées${NC}\"\nelse\n    echo -e \"${RED}❌ Erreur lors de l'installation des dépendances${NC}\"\n    exit 1\nfi\n\n# Setup environment file\nprint_section \"4️⃣  Configuration des variables d'environnement\"\nif [ ! -f .env.local ]; then\n    echo -e \"${YELLOW}📝 Création de .env.local...${NC}\"\n    cat > .env.local << 'EOF'\n# Database\nDATABASE_URL=\"postgresql://postgres:postgres@localhost:5432/adaptive_learning\"\n\n# Redis\nREDIS_URL=\"redis://localhost:6379\"\n\n# NextAuth\nNEXTAUTH_URL=\"http://localhost:3000\"\nNEXTAUTH_SECRET=\"your-secret-key-change-this-in-production-$(date +%s)\"\n\n# Environment\nNODE_ENV=\"development\"\nLOG_LEVEL=\"debug\"\nEOF\n    echo -e \"${GREEN}✅ .env.local créé${NC}\"\nelse\n    echo -e \"${GREEN}✅ .env.local existe déjà${NC}\"\nfi\n\n# Start Docker containers\nprint_section \"5️⃣  Démarrage des services Docker\"\necho -e \"${YELLOW}🐳 Démarrage PostgreSQL et Redis...${NC}\"\n\nif docker-compose up -d postgres redis > /dev/null 2>&1; then\n    echo -e \"${GREEN}✅ Conteneurs Docker démarrés${NC}\"\n    \n    # Wait for database\n    echo -e \"${YELLOW}⏳ Attente de la base de données...${NC}\"\n    sleep 10\n    \n    # Check if database is ready\n    max_attempts=30\n    attempt=0\n    while [ $attempt -lt $max_attempts ]; do\n        if docker exec adaptive-learning-platform-postgres-1 pg_isready -U postgres > /dev/null 2>&1; then\n            echo -e \"${GREEN}✅ PostgreSQL est prêt${NC}\"\n            break\n        fi\n        attempt=$((attempt + 1))\n        echo -n \".\"\n        sleep 1\n    done\n    \n    if [ $attempt -eq $max_attempts ]; then\n        echo -e \"${RED}❌ La base de données n'a pas répondu à temps${NC}\"\n        exit 1\n    fi\nelse\n    echo -e \"${RED}❌ Erreur lors du démarrage des conteneurs${NC}\"\n    exit 1\nfi\n\n# Run Prisma migrations\nprint_section \"6️⃣  Migrations de la base de données\"\necho -e \"${YELLOW}🔄 Exécution des migrations Prisma...${NC}\"\n\nif npm run prisma:migrate -- --skip-generate > /dev/null 2>&1; then\n    echo -e \"${GREEN}✅ Migrations appliquées${NC}\"\nelse\n    echo -e \"${YELLOW}⚠️  Les migrations ont peut-être échoué (c'est normal si la BD existe déjà)${NC}\"\nfi\n\n# Generate Prisma client\nprint_section \"7️⃣  Génération du client Prisma\"\necho -e \"${YELLOW}🔧 Génération du client Prisma...${NC}\"\nif npm run prisma:generate > /dev/null 2>&1; then\n    echo -e \"${GREEN}✅ Client Prisma généré${NC}\"\nelse\n    echo -e \"${YELLOW}⚠️  Erreur lors de la génération (non critique)${NC}\"\nfi\n\n# Success message\nprint_section \"✨ INSTALLATION COMPLÈTE!\"\necho -e \"${GREEN}✅ Tous les services sont prêts!${NC}\\n\"\n\necho -e \"${BLUE}📋 Prochaines étapes:${NC}\"\necho -e \"${YELLOW}1. Ouvrir un terminal et exécuter:${NC}\"\necho -e \"   ${BLUE}npm run dev${NC}\\n\"\necho -e \"${YELLOW}2. Ouvrir votre navigateur:${NC}\"\necho -e \"   ${BLUE}http://localhost:3000${NC}\\n\"\necho -e \"${YELLOW}3. Accédez au Prisma Studio (optionnel):${NC}\"\necho -e \"   ${BLUE}npm run prisma:studio${NC}\\n\"\n\necho -e \"${GREEN}═══════════════════════════════════════════════════════════════${NC}\"\necho -e \"${GREEN}Informations de connexion par défaut:${NC}\"\necho -e \"${BLUE}Email: test@example.com${NC}\"\necho -e \"${BLUE}Mot de passe: password123${NC}\"\necho -e \"${GREEN}═══════════════════════════════════════════════════════════════${NC}\\n\"\n\necho -e \"${YELLOW}💡 Conseils:${NC}\"\necho -e \"   • Gardez les conteneurs Docker en cours d'exécution\"\necho -e \"   • Pour arrêter: docker-compose down\"\necho -e \"   • Pour redémarrer: docker-compose up -d\"\necho -e \"   • Pour voir les logs: docker-compose logs -f\\n\"\n\necho -e \"${GREEN}🎉 Bonne programmation!${NC}\\n\"\n", "path": "setup-local.sh